namespace CopperCPX;
public partial struct CpxEngine<TMemory> where TMemory : struct, ICpxMemory
{
    // CRC32C is linear. Seed its eight basis columns, then expand each byte
    // table by XOR. Constants are generated by eight reflected polynomial
    // steps (base), or 512 steps (64 zero bytes), without initial/final XOR.
    // The tables remain caller-owned; no static array or native allocation.
    private void ExpandCrcTable(uint table)
    {
        memory.Write32(table, 0);
        for (uint basis = 1; basis < 256; basis <<= 1)
        {
            uint column = memory.Read32(table + basis * 4);
            for (uint value = 1; value < basis; value++)
                memory.Write32(table + (basis + value) * 4, memory.Read32(table + value * 4) ^ column);
        }
    }

    private void InitializeCrcTableAt(uint table)
    {
        memory.Write32(table + 4, 0xf26b8303u);
        memory.Write32(table + 8, 0xe13b70f7u);
        memory.Write32(table + 16, 0xc79a971fu);
        memory.Write32(table + 32, 0x8ad958cfu);
        memory.Write32(table + 64, 0x105ec76fu);
        memory.Write32(table + 128, 0x20bd8edeu);
        memory.Write32(table + 256, 0x417b1dbcu);
        memory.Write32(table + 512, 0x82f63b78u);
        ExpandCrcTable(table);
        for (uint n = 0; n < 256; n++)
        {
            uint crc = memory.Read32(table + n * 4);
            for (uint slice = 1; slice < 4; slice++)
            {
                crc = (crc >> 8) ^ memory.Read32(table + (crc & 255) * 4);
                memory.Write32(table + slice * 1024 + n * 4, crc);
            }
        }
    }

    private void InitializeZeroCrcTable()
    {
        uint table = BufferedStorageAddress;
        memory.Write32(table + 4, 0x740eef02u);
        memory.Write32(table + 8, 0xe81dde04u);
        memory.Write32(table + 16, 0xd5d7caf9u);
        memory.Write32(table + 32, 0xae43e303u);
        memory.Write32(table + 64, 0x596bb0f7u);
        memory.Write32(table + 128, 0xb2d761eeu);
        memory.Write32(table + 256, 0x6042b52du);
        memory.Write32(table + 512, 0xc0856a5au);
        ExpandCrcTable(table);
        memory.Write32(table + 1028, 0x84e6a245u);
        memory.Write32(table + 1032, 0x0c21327bu);
        memory.Write32(table + 1040, 0x184264f6u);
        memory.Write32(table + 1056, 0x3084c9ecu);
        memory.Write32(table + 1088, 0x610993d8u);
        memory.Write32(table + 1152, 0xc21327b0u);
        memory.Write32(table + 1280, 0x81ca3991u);
        memory.Write32(table + 1536, 0x067805d3u);
        ExpandCrcTable(table + 1024);
        memory.Write32(table + 2052, 0x0cf00ba6u);
        memory.Write32(table + 2056, 0x19e0174cu);
        memory.Write32(table + 2064, 0x33c02e98u);
        memory.Write32(table + 2080, 0x67805d30u);
        memory.Write32(table + 2112, 0xcf00ba60u);
        memory.Write32(table + 2176, 0x9bed0231u);
        memory.Write32(table + 2304, 0x32367293u);
        memory.Write32(table + 2560, 0x646ce526u);
        ExpandCrcTable(table + 2048);
        memory.Write32(table + 3076, 0xc8d9ca4cu);
        memory.Write32(table + 3080, 0x945fe269u);
        memory.Write32(table + 3088, 0x2d53b223u);
        memory.Write32(table + 3104, 0x5aa76446u);
        memory.Write32(table + 3136, 0xb54ec88cu);
        memory.Write32(table + 3200, 0x6f71e7e9u);
        memory.Write32(table + 3328, 0xdee3cfd2u);
        memory.Write32(table + 3584, 0xb82be955u);
        ExpandCrcTable(table + 3072);
    }

    /// <summary>Builds a caller-owned 4096-byte checksum table for discovery
    /// before mount geometry exists. The caller retains exclusive ownership.</summary>
    public CpxError PrepareAnchorChecksum(uint table)
    {
        if (table == 0 || (table & 3) != 0 || table > uint.MaxValue - 4096) return CpxError.InvalidArgument;
        if ((ulong)table < (ulong)Arena + CpxArena.Scratch && (ulong)Arena < (ulong)table + 4096) return CpxError.InvalidArgument;
        if (R(Signature) == CpxArena.Magic && (R(Waiting) != 0 || R(Finished) == 0 || R(Mounted) != 0 || R(Active) != 0))
            return CpxError.Busy;
        InitializeCrcTableAt(table); return CpxError.None;
    }
}
